{
  "name": "Fault Management Process",
  "resources": [
    {
      "name": "MPO",
      "capacity": 1,
      "resource_type": "human"
    },
    {
      "name": "Fault Detector",
      "capacity": 1,
      "resource_type": "external_party"
    },
    {
      "name": "GO",
      "capacity": 1,
      "resource_type": "external_party"
    },
    {
      "name": "MSP",
      "capacity": 1,
      "resource_type": "external_party"
    }
  ],
  "events": [
    {
      "id": "event_fd_start",
      "name": "Failure detected",
      "event_position": "start",
      "trigger_type": "none",
      "message_name": null
    },
    {
      "id": "event_fd_send_report",
      "name": "Failure reported to MPO",
      "event_position": "end",
      "trigger_type": "message",
      "message_name": "Failure Report"
    },
    {
      "id": "event_mpo_start_fd",
      "name": "Failure report received from FD",
      "event_position": "start",
      "trigger_type": "message",
      "message_name": "Failure Report"
    },
    {
      "id": "event_mpo_start_own",
      "name": "Suspicion of own fault",
      "event_position": "start",
      "trigger_type": "none",
      "message_name": null
    },
    {
      "id": "event_mpo_end_rejected",
      "name": "Failure rejected",
      "event_position": "end",
      "trigger_type": "none",
      "message_name": null
    },
    {
      "id": "event_mpo_notify_go_confirm",
      "name": "Confirmation sent to GO",
      "event_position": "intermediate",
      "trigger_type": "message",
      "message_name": "Failure Confirmation GO"
    },
    {
      "id": "event_go_receive_confirm",
      "name": "Failure confirmation received from MPO",
      "event_position": "start",
      "trigger_type": "message",
      "message_name": "Failure Confirmation GO"
    },
    {
      "id": "event_go_end_confirm",
      "name": "GO informed of failure",
      "event_position": "end",
      "trigger_type": "none",
      "message_name": null
    },
    {
      "id": "event_mpo_notify_msp_confirm",
      "name": "Confirmation sent to MSP",
      "event_position": "intermediate",
      "trigger_type": "message",
      "message_name": "Failure Confirmation MSP"
    },
    {
      "id": "event_msp_receive_confirm",
      "name": "Failure confirmation received from MPO",
      "event_position": "start",
      "trigger_type": "message",
      "message_name": "Failure Confirmation MSP"
    },
    {
      "id": "event_msp_end_confirm",
      "name": "MSP informed of failure",
      "event_position": "end",
      "trigger_type": "none",
      "message_name": null
    },
    {
      "id": "event_mpo_send_repair_results",
      "name": "Repair results sent to FD",
      "event_position": "intermediate",
      "trigger_type": "message",
      "message_name": "Repair Results"
    },
    {
      "id": "event_fd_receive_repair_results",
      "name": "Repair results received from MPO",
      "event_position": "start",
      "trigger_type": "message",
      "message_name": "Repair Results"
    },
    {
      "id": "event_fd_end",
      "name": "FD informed of repairs",
      "event_position": "end",
      "trigger_type": "none",
      "message_name": null
    },
    {
      "id": "event_mpo_send_go_resolution",
      "name": "Interference resolution sent to GO",
      "event_position": "intermediate",
      "trigger_type": "message",
      "message_name": "Resolution Notification GO"
    },
    {
      "id": "event_go_receive_resolution",
      "name": "Interference resolution received from MPO",
      "event_position": "start",
      "trigger_type": "message",
      "message_name": "Resolution Notification GO"
    },
    {
      "id": "event_go_end_resolution",
      "name": "GO informed of resolution",
      "event_position": "end",
      "trigger_type": "none",
      "message_name": null
    },
    {
      "id": "event_mpo_send_msp_resolution",
      "name": "Interference resolution sent to MSP",
      "event_position": "intermediate",
      "trigger_type": "message",
      "message_name": "Resolution Notification MSP"
    },
    {
      "id": "event_msp_receive_resolution",
      "name": "Interference resolution received from MPO",
      "event_position": "start",
      "trigger_type": "message",
      "message_name": "Resolution Notification MSP"
    },
    {
      "id": "event_msp_end_resolution",
      "name": "MSP informed of resolution",
      "event_position": "end",
      "trigger_type": "none",
      "message_name": null
    },
    {
      "id": "event_mpo_end_process",
      "name": "Fault resolution process completed",
      "event_position": "end",
      "trigger_type": "none",
      "message_name": null
    }
  ],
  "tasks": [
    {
      "id": "task_fd_report_failure",
      "name": "Report failure to MPO",
      "bpmn_type": "bpmn:Task",
      "resource_name": "Fault Detector",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [],
      "output_data_ids": [
        "data_obj_failure_report"
      ]
    },
    {
      "id": "task_mpo_examine_failure",
      "name": "Examine the failure",
      "bpmn_type": "bpmn:UserTask",
      "resource_name": "MPO",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [
        "data_obj_failure_report"
      ],
      "output_data_ids": []
    },
    {
      "id": "task_mpo_fix_fault",
      "name": "Fix the fault at the measuring device",
      "bpmn_type": "bpmn:ManualTask",
      "resource_name": "MPO",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [],
      "output_data_ids": [
        "data_obj_repair_results"
      ]
    }
  ],
  "gateways": [
    {
      "id": "gw_mpo_start_merge",
      "name": "Start trigger merge",
      "gateway_type": "exclusive",
      "branch_probabilities": null,
      "branch_conditions": null
    },
    {
      "id": "gw_mpo_decision",
      "name": "Failure confirmed?",
      "gateway_type": "exclusive",
      "branch_probabilities": null,
      "branch_conditions": [
        {
          "flow_id": "sf_gw_mpo_dec_to_rejected",
          "condition": "Rejects the failure"
        },
        {
          "flow_id": "sf_gw_mpo_dec_to_par_notify",
          "condition": "Confirms the failure"
        }
      ]
    },
    {
      "id": "gw_mpo_par_notify_split",
      "name": "Inform GO and MSP split",
      "gateway_type": "parallel",
      "branch_probabilities": null,
      "branch_conditions": null
    },
    {
      "id": "gw_mpo_par_notify_join",
      "name": "Inform GO and MSP join",
      "gateway_type": "parallel",
      "branch_probabilities": null,
      "branch_conditions": null
    },
    {
      "id": "gw_mpo_par_resolution_split",
      "name": "Inform resolution split",
      "gateway_type": "parallel",
      "branch_probabilities": null,
      "branch_conditions": null
    },
    {
      "id": "gw_mpo_par_resolution_join",
      "name": "Inform resolution join",
      "gateway_type": "parallel",
      "branch_probabilities": null,
      "branch_conditions": null
    }
  ],
  "sequence_flows": [
    {
      "id": "sf_fd_1",
      "source_id": "event_fd_start",
      "target_id": "task_fd_report_failure",
      "condition_name": null
    },
    {
      "id": "sf_fd_2",
      "source_id": "task_fd_report_failure",
      "target_id": "event_fd_send_report",
      "condition_name": null
    },
    {
      "id": "sf_fd_rec_repair",
      "source_id": "event_fd_receive_repair_results",
      "target_id": "event_fd_end",
      "condition_name": null
    },
    {
      "id": "sf_mpo_start_fd",
      "source_id": "event_mpo_start_fd",
      "target_id": "gw_mpo_start_merge",
      "condition_name": null
    },
    {
      "id": "sf_mpo_start_own",
      "source_id": "event_mpo_start_own",
      "target_id": "gw_mpo_start_merge",
      "condition_name": null
    },
    {
      "id": "sf_mpo_merge_to_examine",
      "source_id": "gw_mpo_start_merge",
      "target_id": "task_mpo_examine_failure",
      "condition_name": null
    },
    {
      "id": "sf_mpo_examine_to_gw_dec",
      "source_id": "task_mpo_examine_failure",
      "target_id": "gw_mpo_decision",
      "condition_name": null
    },
    {
      "id": "sf_gw_mpo_dec_to_rejected",
      "source_id": "gw_mpo_decision",
      "target_id": "event_mpo_end_rejected",
      "condition_name": "Rejects the failure"
    },
    {
      "id": "sf_gw_mpo_dec_to_par_notify",
      "source_id": "gw_mpo_decision",
      "target_id": "gw_mpo_par_notify_split",
      "condition_name": "Confirms the failure"
    },
    {
      "id": "sf_mpo_notify_go",
      "source_id": "gw_mpo_par_notify_split",
      "target_id": "event_mpo_notify_go_confirm",
      "condition_name": null
    },
    {
      "id": "sf_mpo_notify_msp",
      "source_id": "gw_mpo_par_notify_split",
      "target_id": "event_mpo_notify_msp_confirm",
      "condition_name": null
    },
    {
      "id": "sf_mpo_go_confirm_to_join",
      "source_id": "event_mpo_notify_go_confirm",
      "target_id": "gw_mpo_par_notify_join",
      "condition_name": null
    },
    {
      "id": "sf_mpo_msp_confirm_to_join",
      "source_id": "event_mpo_notify_msp_confirm",
      "target_id": "gw_mpo_par_notify_join",
      "condition_name": null
    },
    {
      "id": "sf_mpo_notify_join_to_fix",
      "source_id": "gw_mpo_par_notify_join",
      "target_id": "task_mpo_fix_fault",
      "condition_name": null
    },
    {
      "id": "sf_mpo_fix_to_res_split",
      "source_id": "task_mpo_fix_fault",
      "target_id": "gw_mpo_par_resolution_split",
      "condition_name": null
    },
    {
      "id": "sf_mpo_res_split_to_fd",
      "source_id": "gw_mpo_par_resolution_split",
      "target_id": "event_mpo_send_repair_results",
      "condition_name": null
    },
    {
      "id": "sf_mpo_res_split_to_go",
      "source_id": "gw_mpo_par_resolution_split",
      "target_id": "event_mpo_send_go_resolution",
      "condition_name": null
    },
    {
      "id": "sf_mpo_res_split_to_msp",
      "source_id": "gw_mpo_par_resolution_split",
      "target_id": "event_mpo_send_msp_resolution",
      "condition_name": null
    },
    {
      "id": "sf_mpo_fd_res_to_join",
      "source_id": "event_mpo_send_repair_results",
      "target_id": "gw_mpo_par_resolution_join",
      "condition_name": null
    },
    {
      "id": "sf_mpo_go_res_to_join",
      "source_id": "event_mpo_send_go_resolution",
      "target_id": "gw_mpo_par_resolution_join",
      "condition_name": null
    },
    {
      "id": "sf_mpo_msp_res_to_join",
      "source_id": "event_mpo_send_msp_resolution",
      "target_id": "gw_mpo_par_resolution_join",
      "condition_name": null
    },
    {
      "id": "sf_mpo_res_join_to_end",
      "source_id": "gw_mpo_par_resolution_join",
      "target_id": "event_mpo_end_process",
      "condition_name": null
    },
    {
      "id": "sf_go_confirm_to_end",
      "source_id": "event_go_receive_confirm",
      "target_id": "event_go_end_confirm",
      "condition_name": null
    },
    {
      "id": "sf_go_resolution_to_end",
      "source_id": "event_go_receive_resolution",
      "target_id": "event_go_end_resolution",
      "condition_name": null
    },
    {
      "id": "sf_msp_confirm_to_end",
      "source_id": "event_msp_receive_confirm",
      "target_id": "event_msp_end_confirm",
      "condition_name": null
    },
    {
      "id": "sf_msp_resolution_to_end",
      "source_id": "event_msp_receive_resolution",
      "target_id": "event_msp_end_resolution",
      "condition_name": null
    }
  ],
  "pools": [
    {
      "id": "pool_fd",
      "name": "Fault Detector",
      "element_ids": [
        "event_fd_start",
        "task_fd_report_failure",
        "event_fd_send_report",
        "event_fd_receive_repair_results",
        "event_fd_end"
      ]
    },
    {
      "id": "pool_mpo",
      "name": "MPO",
      "element_ids": [
        "event_mpo_start_fd",
        "event_mpo_start_own",
        "gw_mpo_start_merge",
        "task_mpo_examine_failure",
        "gw_mpo_decision",
        "event_mpo_end_rejected",
        "gw_mpo_par_notify_split",
        "event_mpo_notify_go_confirm",
        "event_mpo_notify_msp_confirm",
        "gw_mpo_par_notify_join",
        "task_mpo_fix_fault",
        "gw_mpo_par_resolution_split",
        "event_mpo_send_repair_results",
        "event_mpo_send_go_resolution",
        "event_mpo_send_msp_resolution",
        "gw_mpo_par_resolution_join",
        "event_mpo_end_process"
      ]
    },
    {
      "id": "pool_go",
      "name": "GO",
      "element_ids": [
        "event_go_receive_confirm",
        "event_go_end_confirm",
        "event_go_receive_resolution",
        "event_go_end_resolution"
      ]
    },
    {
      "id": "pool_msp",
      "name": "MSP",
      "element_ids": [
        "event_msp_receive_confirm",
        "event_msp_end_confirm",
        "event_msp_receive_resolution",
        "event_msp_end_resolution"
      ]
    }
  ],
  "message_flows": [
    {
      "id": "mf_fd_report_to_mpo",
      "source_id": "event_fd_send_report",
      "target_id": "event_mpo_start_fd",
      "name": "Failure Report"
    },
    {
      "id": "mf_mpo_confirm_to_go",
      "source_id": "event_mpo_notify_go_confirm",
      "target_id": "event_go_receive_confirm",
      "name": "Failure Confirmation GO"
    },
    {
      "id": "mf_mpo_confirm_to_msp",
      "source_id": "event_mpo_notify_msp_confirm",
      "target_id": "event_msp_receive_confirm",
      "name": "Failure Confirmation MSP"
    },
    {
      "id": "mf_mpo_repair_results_to_fd",
      "source_id": "event_mpo_send_repair_results",
      "target_id": "event_fd_receive_repair_results",
      "name": "Repair Results"
    },
    {
      "id": "mf_mpo_resolution_to_go",
      "source_id": "event_mpo_send_go_resolution",
      "target_id": "event_go_receive_resolution",
      "name": "Resolution Notification GO"
    },
    {
      "id": "mf_mpo_resolution_to_msp",
      "source_id": "event_mpo_send_msp_resolution",
      "target_id": "event_msp_receive_resolution",
      "name": "Resolution Notification MSP"
    }
  ],
  "data_objects": [
    {
      "id": "data_obj_failure_report",
      "name": "Failure Report"
    },
    {
      "id": "data_obj_repair_results",
      "name": "Repair Results Document"
    }
  ],
  "data_stores": [],
  "inter_arrival_time": {
    "distribution": "fixed",
    "value": 1.0,
    "unit": "minutes",
    "is_placeholder": true,
    "source": "default_missing_duration"
  },
  "simulation_duration": null,
  "simulation_duration_unit": "hours"
}
